#include <string>
#include <vector>
#include <numeric>

class Solution {
public:
    long long numberOfSubstrings(std::string s) {
        std::vector<long long> count(26, 0);
        for (char c : s) {
            count[c - 'a']++;
        }
        long long total = 0;
        for (long long c : count) {
            total += c * (c + 1) / 2;
        }
        return total;
    }
};

class Solution {
    public long numberOfSubstrings(String s) {
        long[] count = new long[26];
        for (int i = 0; i < s.length(); i++) {
            count[s.charAt(i) - 'a']++;
        }
        long total = 0;
        for (long c : count) {
            total += c * (c + 1) / 2;
        }
        return total;
    }
}

/**
 * @param {string} s
 * @return {number}
 */
var numberOfSubstrings = function(s) {
    const count = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) {
        count[s.charCodeAt(i) - 97]++;
    }
    let total = 0;
    for (const c of count) {
        total += (c * (c + 1)) / 2;
    }
    return total;
};
